import{_ as a,o as n,c as t,a6 as p}from"./chunks/framework.Buk0QMEt.js";const g=JSON.parse('{"title":"为什么一个视频能让全国人民同时秒开？","description":"","frontmatter":{"title":"为什么一个视频能让全国人民同时秒开？","date":"2026-06-15T00:00:00.000Z","categories":"社区","tags":["CDN","网络原理","系统设计"]},"headers":[],"relativePath":"content/社区/为什么一个视频能让全国人民同时秒开.md","filePath":"content/社区/为什么一个视频能让全国人民同时秒开.md","lastUpdated":1781514358000}'),e={name:"content/社区/为什么一个视频能让全国人民同时秒开.md"};function o(i,s,l,r,d,c){return n(),t("div",null,[...s[0]||(s[0]=[p(`<blockquote><p>作者：沉默是金，总会发光 原文：<a href="https://juejin.cn/post/7623634379211259956" target="_blank" rel="noreferrer">https://juejin.cn/post/7623634379211259956</a></p></blockquote><hr><p>你有没有想过一个问题：</p><p><strong>为什么一个视频刚发布，全国几百万用户同时点开，居然还能秒加载？</strong></p><p>如果所有请求都直接打到服务器上，理论上是这样的：</p><p>$$100万人同时访问 → 请求全部打到一台服务器 → 服务器CPU爆炸 → 网站直接挂掉$$</p><p>但现实并不是这样。原因只有三个字：<strong>CDN</strong>。</p><hr><h2 id="_01-没有-cdn-时-请求是怎么跑的" tabindex="-1">01 没有 CDN 时，请求是怎么跑的？ <a class="header-anchor" href="#_01-没有-cdn-时-请求是怎么跑的" aria-label="Permalink to &quot;01 没有 CDN 时，请求是怎么跑的？&quot;">​</a></h2><p>假设你在<strong>北京</strong>，想从<strong>上海</strong>买一箱苹果。</p><p>没有任何中转仓库的时候，流程是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你（北京）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>上海果园</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>快递翻山越岭</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>你收到苹果</span></span></code></pre></div><p>大概需要 <strong>3 ~ 5 天</strong>。</p><p>网络请求其实是一样的。比如你的服务器在<strong>上海</strong>，而用户在<strong>北京</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京用户</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>互联网</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>上海服务器</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>返回数据</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>北京用户</span></span></code></pre></div><p>一次网络往返大概需要 <strong>100ms ~ 300ms</strong>。</p><p>如果用户在<strong>新疆</strong>，延迟甚至可能到 <strong>500ms</strong>。</p><p>这还不是最可怕的。真正的问题是：</p><blockquote><p>100万人同时看视频 → 100万个请求 → 全部打到上海服务器 → 服务器直接崩溃</p></blockquote><p>所以互联网必须解决两个问题：</p><ol><li><strong>距离太远，延迟高</strong></li><li><strong>请求太多，服务器扛不住</strong></li></ol><p>于是 CDN 诞生了。</p><hr><h2 id="_02-cdn-的核心思想" tabindex="-1">02 CDN 的核心思想 <a class="header-anchor" href="#_02-cdn-的核心思想" aria-label="Permalink to &quot;02 CDN 的核心思想&quot;">​</a></h2><p>CDN 的思路其实非常简单：</p><p><strong>把内容复制到离用户最近的地方。</strong></p><p>还是刚才的苹果例子。如果快递公司在全国建了很多仓库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京仓 · 上海仓 · 广州仓 · 成都仓</span></span></code></pre></div><p>那北京用户买苹果时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京用户 → 北京仓库 → 当天送达</span></span></code></pre></div><p><strong>根本不需要从上海运。</strong></p><p>网络也是一样。有了 CDN 之后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京用户 → 北京CDN节点 → 直接返回资源</span></span></code></pre></div><p>延迟可能只有 <strong>5ms ~ 10ms</strong>。</p><p>这就是 CDN 的本质：<strong>把内容缓存到离用户最近的服务器。</strong></p><p>CDN 的全称是：<strong>Content Delivery Network</strong>，中文叫：<strong>内容分发网络</strong>。</p><hr><h2 id="cdn-是怎么工作的" tabindex="-1">CDN 是怎么工作的？ <a class="header-anchor" href="#cdn-是怎么工作的" aria-label="Permalink to &quot;CDN 是怎么工作的？&quot;">​</a></h2><p>整个过程分三步：</p><h3 id="_1-dns-智能解析" tabindex="-1">1. DNS 智能解析 <a class="header-anchor" href="#_1-dns-智能解析" aria-label="Permalink to &quot;1. DNS 智能解析&quot;">​</a></h3><p>当你输入 <code>www.example.com</code>，浏览器会先去问 DNS：这个域名对应哪个 IP？</p><ul><li><strong>没有 CDN</strong>：DNS → 返回固定IP → 上海服务器</li><li><strong>有 CDN</strong>：DNS 会根据你的<strong>地理位置</strong>返回不同节点</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京用户 → 返回北京CDN节点IP</span></span>
<span class="line"><span>新疆用户 → 返回新疆CDN节点IP</span></span>
<span class="line"><span>广州用户 → 返回广州CDN节点IP</span></span></code></pre></div><p>这个过程叫 <strong>GSLB（全局负载均衡）</strong>，作用就是：<strong>把用户分配到最近的服务器。</strong></p><h3 id="_2-边缘节点响应" tabindex="-1">2. 边缘节点响应 <a class="header-anchor" href="#_2-边缘节点响应" aria-label="Permalink to &quot;2. 边缘节点响应&quot;">​</a></h3><p>CDN 在全国会部署大量服务器，这些服务器叫 <strong>PoP（Point of Presence）</strong>，也叫<strong>边缘节点</strong>。</p><p>简单理解就是：<strong>全国各地的小仓库。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京PoP · 上海PoP · 广州PoP · 成都PoP · 新疆PoP</span></span></code></pre></div><p>用户访问时：<strong>用户 → 最近CDN节点 → 返回资源</strong></p><p>如果资源已经缓存，就直接返回，速度极快。</p><h3 id="_3-缓存未命中时回源" tabindex="-1">3. 缓存未命中时回源 <a class="header-anchor" href="#_3-缓存未命中时回源" aria-label="Permalink to &quot;3. 缓存未命中时回源&quot;">​</a></h3><p>如果 CDN 节点没有缓存资源，就会：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 → CDN节点 → 源站服务器 → 返回资源 → CDN缓存</span></span></code></pre></div><p>这个过程叫<strong>回源</strong>。</p><p>下一次用户再访问：<strong>用户 → CDN节点 → 直接返回缓存</strong>，源站压力瞬间降低。</p><hr><h2 id="_03-cdn-为什么能-秒开" tabindex="-1">03 CDN 为什么能&quot;秒开&quot;？ <a class="header-anchor" href="#_03-cdn-为什么能-秒开" aria-label="Permalink to &quot;03 CDN 为什么能&quot;秒开&quot;？&quot;">​</a></h2><p>主要有三个原因：</p><h3 id="_1-物理距离更近" tabindex="-1">1. 物理距离更近 <a class="header-anchor" href="#_1-物理距离更近" aria-label="Permalink to &quot;1. 物理距离更近&quot;">​</a></h3><table tabindex="0"><thead><tr><th>访问路径</th><th>延迟</th></tr></thead><tbody><tr><td>北京 → 上海服务器</td><td>200ms</td></tr><tr><td>北京 → 北京CDN节点</td><td>5ms</td></tr></tbody></table><p><strong>速度差：40 倍。</strong> 原因只有一个：距离更近。</p><h3 id="_2-cdn有专属骨干网络" tabindex="-1">2. CDN有专属骨干网络 <a class="header-anchor" href="#_2-cdn有专属骨干网络" aria-label="Permalink to &quot;2. CDN有专属骨干网络&quot;">​</a></h3><p>普通互联网的路径可能是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京 → 西安 → 成都 → 上海</span></span></code></pre></div><p>每一跳都会增加延迟。</p><p>但大型 CDN 会自建专线网络：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京PoP ↔ 上海PoP ↔ 源站</span></span></code></pre></div><p>类似<strong>互联网高铁</strong>，跳数更少，延迟更低。</p><h3 id="_3-缓存复用" tabindex="-1">3. 缓存复用 <a class="header-anchor" href="#_3-缓存复用" aria-label="Permalink to &quot;3. 缓存复用&quot;">​</a></h3><p>如果100万人看同一个视频：</p><ul><li><strong>没有CDN</strong>：100万请求 → 全部打到服务器</li><li><strong>有CDN</strong>：第1个人访问 → CDN回源；后面 999,999 人 → 全部命中缓存</li></ul><p><strong>服务器只需要处理一次请求。</strong></p><hr><h2 id="_04-总结" tabindex="-1">04 总结 <a class="header-anchor" href="#_04-总结" aria-label="Permalink to &quot;04 总结&quot;">​</a></h2><p>现在的 CDN 已经进化成了<strong>边缘计算平台</strong>。很多事情可以在 CDN 节点完成：</p><ul><li>静态资源缓存</li><li>图片压缩</li><li>WebP / AVIF 转换</li><li>TLS / SSL 加密</li><li>防 DDoS 攻击</li><li>动态请求加速</li><li>A/B 测试</li><li>Edge Functions</li></ul><p>也就是说：<strong>CDN 不只是送快递，它还可以在仓库里直接加工商品。</strong></p><p>用一个最简单的比喻：</p><table tabindex="0"><thead><tr><th>角色</th><th>对应</th></tr></thead><tbody><tr><td>源站服务器</td><td>🏭 工厂</td></tr><tr><td>CDN节点</td><td>🏪 全国仓库</td></tr><tr><td>用户</td><td>🧑 买家</td></tr></tbody></table><p>流程就是：<strong>工厂生产 → 全国仓库存货 → 用户就近购买</strong></p><p>所以 CDN 的本质其实很简单：<strong>在全国建很多仓库，就近发货。</strong></p><hr><p>现在你应该理解了：为什么一个视频发布后，几百万用户同时观看却还能秒开？</p><p><strong>因为在你点击播放的那一刻，并不是一台服务器在工作，而是遍布全国、甚至全球的 CDN 节点在帮你跑腿。</strong></p><p>技术看起来很复杂，但本质其实只有一句话：</p><blockquote><p><strong>把内容放到离用户最近的地方。</strong></p></blockquote>`,86)])])}const u=a(e,[["render",o]]);export{g as __pageData,u as default};
